function minMeetingRooms(intervals) {
  // Two sorted lists: when sessions start, and when they end.
  const starts = intervals.map((interval) => interval[0]).sort((a, b) => a - b);
  const ends = intervals.map((interval) => interval[1]).sort((a, b) => a - b);

  let roomsInUse = 0;
  let maxRooms = 0;
  let endIndex = 0;
  for (let i = 0; i < starts.length; i++) {
    // Free every room whose session ended at or before this start.
    while (endIndex < ends.length && ends[endIndex] <= starts[i]) {
      roomsInUse--;
      endIndex++;
    }
    roomsInUse++;
    maxRooms = Math.max(maxRooms, roomsInUse);
  }
  return maxRooms;
}
